-- MCQ FORM — rule mới cho nhánh "sinh nhiễu từ đáp số" (DẠNG 52, mini-dang.mjs) sau sự cố 18/10.
-- Sự cố: parser cũ tách "12,61" thành 2 số "12;61", đọc "30 000" thành 0 ⇒ 451 form đã duyệt hiện phương án vô nghĩa
-- (chủ yếu Toán 5, số thập phân). Parser mới (scripts/lib/so-vn.mjs) đọc đúng phẩy thập phân / cách hàng nghìn và giữ
-- KHUÔN viết của đáp số; các rule cũ R343–R346 ("lệch 1 đơn vị", "gấp đôi") vô nghĩa với số thập phân nên thêm:
--   R363–R367: lỗi thật với số thập phân (đặt sai dấu phẩy, sót/thừa chữ số 0, lệch chữ số cuối, quên phần nguyên)
--   R368–R370: câu SẮP XẾP dãy số (nhiễu = hoán vị chính các số đề cho, không bịa số mới)
--   R103 (đã có, "Lệch một chữ số 0"): mở thêm cho các dạng số nguyên có cách hàng nghìn.
-- Kiểm trước khi đặt mã: select max((regexp_replace(ma,'[^0-9]','','g'))::int) from dai_mcq_rule  → 362 (18/10 09:50).
insert into dai_mcq_rule (ma, ten, mo_ta, vi_du, nhom, ap_dung, du_phong) values
('R363', 'Số thập phân: đặt dấu phẩy lệch sang phải 1 hàng', 'Đặt tính / đổi đơn vị đúng các chữ số nhưng đặt dấu phẩy lệch 1 hàng sang phải — kết quả gấp 10 lần', 'Đúng $12{,}61$ → nhầm $126{,}1$', 'tinh', '{T105040103,T105040105,T105040107,T105040108,T105040110,T105040201,T105040202,T105040203,T105040204,T105040205,T105040206,T105040207,T105040208,T105040209,T105100203,T105100204,T105100402,T105100405,T105100407,T105100408,T107020102,T107020401,T110020204,T110030203,T111030105,T111040301,T111050402,T111060304,T15T020201,T15T020202,T15T020203,T15T020204}', false),
('R364', 'Số thập phân: đặt dấu phẩy lệch sang trái 1 hàng', 'Đặt tính / đổi đơn vị đúng các chữ số nhưng đặt dấu phẩy lệch 1 hàng sang trái — kết quả bằng 1/10', 'Đúng $12{,}61$ → nhầm $1{,}261$', 'tinh', '{T105040103,T105040105,T105040107,T105040108,T105040110,T105040201,T105040202,T105040203,T105040204,T105040205,T105040206,T105040207,T105040208,T105040209,T105100203,T105100204,T105100402,T105100405,T105100407,T105100408,T107020102,T107020401,T110020204,T110030203,T111030105,T111040301,T111050402,T111060304,T15T020201,T15T020202,T15T020203,T15T020204}', false),
('R365', 'Bỏ sót / viết thừa chữ số 0', 'Số thập phân: bỏ sót chữ số 0 ngay sau dấu phẩy (0,08 → 0,8; 7,05 → 7,5), không có thì viết thừa (12,61 → 12,061). Số nguyên nhiều chữ số: viết sót hoặc thừa một chữ số 0 (50 714 → 5 714)', 'Đúng $0{,}08$ → nhầm $0{,}8$', 'khai_niem', '{T104010101,T104010103,T104010302,T105010103,T105010104,T105040103,T105040105,T105040107,T105040108,T105040110,T105040201,T105040202,T105040203,T105040204,T105040205,T105040206,T105040207,T105040208,T105040209,T105100203,T105100204,T105100402,T105100405,T105100407,T105100408,T106020207,T107020102,T107020401,T110020204,T110030203,T111030105,T111040301,T111050402,T111060304,T15T020201,T15T020202,T15T020203,T15T020204}', false),
('R366', 'Số thập phân: lệch 1 đơn vị ở chữ số cuối', 'Rule dự phòng — đúng cách làm nhưng tính lệch 1 đơn vị ở chữ số thập phân cuối cùng', 'Đúng $12{,}61$ → nhầm $12{,}62$', 'tinh', '{T105040103,T105040105,T105040107,T105040108,T105040110,T105040201,T105040202,T105040203,T105040204,T105040205,T105040206,T105040207,T105040208,T105040209,T105100203,T105100204,T105100402,T105100405,T105100407,T105100408,T107020102,T107020401,T110020204,T110030203,T111030105,T111040301,T111050402,T111060304,T15T020201,T15T020202,T15T020203,T15T020204}', true),
('R367', 'Số thập phân: quên phần nguyên', 'Đổi phân số / hỗn số / số đo sang số thập phân nhưng chỉ viết phần thập phân, quên phần nguyên', 'Đúng $10{,}145$ → nhầm $0{,}145$', 'khai_niem', '{T105040103,T105040105,T105040107,T105040108,T105100203,T105100204}', false),
('R368', 'Sắp xếp: ngược chiều', 'Sắp xếp đúng thứ tự nhưng ngược chiều đề yêu cầu (bé đến lớn ↔ lớn đến bé)', 'Bé đến lớn 63 578; 526 395; 562 395 → nhầm 562 395; 526 395; 63 578', 'khai_niem', '{T105010103}', false),
('R369', 'Sắp xếp: nhầm 2 số gần nhau', 'So sánh nhầm 2 số đứng cạnh nhau có giá trị gần nhau nhất (cùng số chữ số, khác 1–2 chữ số) nên đổi chỗ chúng', '526 395 và 562 395 đổi chỗ', 'tinh', '{T105010103}', false),
('R370', 'Sắp xếp: so theo chữ số đầu tiên', 'So sánh số theo chữ số đầu tiên như so chữ, không đếm số chữ số trước', '63 578 xếp sau 5 628 723 vì 6 > 5', 'khai_niem', '{T105010103}', false);

update dai_mcq_rule set ap_dung = (select array_agg(distinct x order by x) from unnest(ap_dung || '{T104010101,T104010103,T104010302,T105010103,T105010104,T106020207}'::text[]) x) where ma = 'R103';
